using Godot;
using System;
using System.Linq;
using Settings=Godot.Collections.Dictionary;
public partial class TimelinePhysicsOperations
{
    private static string Warnings(RefCounted owner)=>string.Join(" · ",owner.Get("_warnings").AsGodotArray().Select(value=>value.AsString()));
    private static void Status(RefCounted owner,string text){owner.Set("status",text);owner.EmitSignal("status_changed",text);}
    public void evaluate(RefCounted owner,RefCounted model,Settings runtimes,double time,int budget)
    {
        owner.Set("_model",model);owner.Set("_runtimes",runtimes);bool geometry=false;foreach(var value in model.Get("actors").AsGodotArray())if(_settings.configured(value.As<Resource>())){geometry=true;break;}foreach(var value in runtimes.Values){var node=value.AsGodotObject();if(!GodotObject.IsInstanceValid(node))continue;if(node.HasMethod("physics_geometry_error")){string error=node.Call("physics_geometry_error").AsString();if(error.Length>0){owner.Set("pending",false);Status(owner,"Environment geometry failed: "+error);return;}}if(node.HasMethod("physics_geometry_ready")&&!node.Call("physics_geometry_ready",geometry).AsBool()){owner.Set("pending",true);Status(owner,"Preparing environment geometry");return;}}
        if(owner.Get("dirty").AsBool()){string signature=_settings.fingerprint(model);if(signature!=owner.Get("signature").AsString())setup(owner,model,runtimes,signature);owner.Set("dirty",false);}if(Map(owner,"prototypes").Count==0){owner.Set("pending",false);Status(owner,Warnings(owner));return;}double origin=owner.Get("origin").AsDouble(),rate=owner.Get("rate").AsDouble(),exact=Math.Max(0,(time-origin)*rate);long target=(long)Math.Floor(exact+.0000001);double fraction=exact-target;long goal=target+(fraction>.000001?1:0);double requested=owner.Get("requested_time").AsDouble();long step=owner.Get("step").AsInt64();if(!Mathf.IsEqualApprox(requested,time)||double.IsNaN(requested)){owner.Set("requested_time",time);if(step>target){long checkpoint=0;var checkpoints=Map(owner,"checkpoints");foreach(var key in checkpoints.Keys){long index=key.AsInt64();if(index<=target)checkpoint=Math.Max(checkpoint,index);}owner.Set("states",snapshot(checkpoints[checkpoint].AsGodotDictionary()));step=checkpoint;owner.Set("step",step);owner.Set("_floor_step",-1);}}
        if(step==target){owner.Set("_floor_states",snapshot(Map(owner,"states")));owner.Set("_floor_step",target);}int count=0;ulong deadline=Godot.Time.GetTicksUsec()+12000;while(step<goal&&count<budget&&(count==0||Godot.Time.GetTicksUsec()<deadline)){this.step(owner,origin+(step+1)/rate,1/rate);step++;owner.Set("step",step);count++;owner.Set("steps_taken",owner.Get("steps_taken").AsInt64()+1);cache(owner);if(step==target){owner.Set("_floor_states",snapshot(Map(owner,"states")));owner.Set("_floor_step",target);}}bool pending=step<goal;owner.Set("pending",pending);
        if(!pending){var display=snapshot(Map(owner,"states"));owner.Set("display_states",display);if(fraction>.000001&&owner.Get("_floor_step").AsInt64()==target){var floor=Map(owner,"_floor_states");foreach(var id in display.Keys){var value=display[id].AsGodotDictionary();var left=floor[id].AsGodotDictionary();value["pose"]=left["pose"].AsTransform3D().InterpolateWith(value["pose"].AsTransform3D(),(float)fraction);interpolate_points(value,left,value.Duplicate(true),fraction);var bones=value["bones"].AsGodotDictionary();var previous=left["bones"].AsGodotDictionary();foreach(var bone in bones.Keys)if(previous.TryGetValue(bone,out var initial)){var current=bones[bone].AsGodotDictionary();current["pose"]=initial.AsGodotDictionary()["pose"].AsTransform3D().InterpolateWith(current["pose"].AsTransform3D(),(float)fraction);}}}owner.Set("_applied_time",time);owner.Set("base_display_states",snapshot(display));}Status(owner,pending?"Preparing physics "+(origin+step/rate).ToString("F2",System.Globalization.CultureInfo.InvariantCulture)+" / "+time.ToString("F2",System.Globalization.CultureInfo.InvariantCulture)+" s":Warnings(owner));apply(owner,time);
    }
}
